text:
# Default AgentShield policy for the customer-support world.
# Anything not listed is denied: unknown agents, and tools an agent does not list.
version: 1

agents:
  support_agent:
    description: Front-line support. Small refunds, single-record lookups, customer email.
    tools:
      get_customer:   {allow: true, scope: single_record}
      get_order:      {allow: true}
      get_ticket:     {allow: true}
      issue_refund:   {allow: true, max_amount_inr: 5000, approval_above_inr: 2000}
      update_ticket:  {allow: true}
      send_email:     {allow: true, allowed_domains: [customer-domain, company.com]}
      query_database: {allow: true, deny_patterns: ["(?i)SELECT\\s+\\*", "(?i)\\bLIMIT\\s+\\d{3,}"], max_rows: 10}
      read_secret:    {allow: false}
      encode:         {allow: true}

  finance_agent:
    description: Finance team. Large refunds, with approval above ₹25,000.
    tools:
      get_customer:   {allow: true, scope: single_record}
      get_order:      {allow: true}
      issue_refund:   {allow: true, max_amount_inr: 100000, approval_above_inr: 25000}
      update_ticket:  {allow: true}
      send_email:     {allow: true, allowed_domains: [customer-domain, company.com]}

  ops_agent:
    description: Platform operations. May read service credentials to run integrations; must never send them anywhere.
    tools:
      get_customer:   {allow: true, scope: single_record}
      get_order:      {allow: true}
      issue_refund:   {allow: true, max_amount_inr: 5000, approval_above_inr: 2000}
      update_ticket:  {allow: true}
      send_email:     {allow: true, allowed_domains: [customer-domain, company.com]}
      query_database: {allow: true, deny_patterns: ["(?i)SELECT\\s+\\*", "(?i)\\bLIMIT\\s+\\d{3,}"], max_rows: 10}
      read_secret:    {allow: true}
      encode:         {allow: true}

  # RefundOps (agentguard/ops/refunds.py): one identity per agent, least privilege each.
  intake_agent:
    description: RefundOps intake. Reads the support inbox and changes nothing.
    tools:
      list_tickets:   {allow: true}
      get_ticket:     {allow: true}

  decision_agent:
    description: RefundOps eligibility checks. Read-only.
    tools:
      get_ticket:     {allow: true}
      get_customer:   {allow: true, scope: single_record}
      get_order:      {allow: true}

  action_agent:
    description: RefundOps execution. Refunds within limits, ticket updates, email to customers only.
    tools:
      get_order:      {allow: true}
      issue_refund:   {allow: true, max_amount_inr: 5000, approval_above_inr: 2000}
      update_ticket:  {allow: true}
      send_email:     {allow: true, allowed_domains: [customer-domain]}

  reporting_agent:
    description: RefundOps outcome reporting. Read-only.
    tools:
      get_order:      {allow: true}
      get_ticket:     {allow: true}

  # AccessOps (agentguard/ops/access.py), IT Infrastructure: identity and access requests.
  access_intake_agent:
    description: AccessOps intake. Reads the access-request queue and changes nothing.
    tools:
      list_access_requests: {allow: true}
      get_access_request:   {allow: true}

  access_decision_agent:
    description: AccessOps eligibility checks. Read-only.
    tools:
      get_access_request:   {allow: true}
      get_user:             {allow: true, scope: single_record}
      get_system:           {allow: true}
      list_grants:          {allow: true}

  access_action_agent:
    description: AccessOps execution. Grants exactly what was requested, updates requests, notifies employees.
    tools:
      grant_access:          {allow: true}
      update_access_request: {allow: true}
      notify:                {allow: true, allowed_domains: [company.com]}

  access_reporting_agent:
    description: AccessOps outcome reporting. Read-only.
    tools:
      list_grants:          {allow: true}
      get_access_request:   {allow: true}

rules:
  - id: no_duplicate_refund
    description: An order must not be refunded twice for the same amount.
    when: {tool: issue_refund}
    # Re-using an idempotency key is a safe replay; a new key for an already-refunded amount is a duplicate.
    check: "ledger.refund_key_exists(idempotency_key) or ledger.successful_refunds(order_id, amount_inr) == 0"
    on_fail: BLOCK
    risk: HIGH
    message: "Order already has a successful refund of this amount; a retry with a new idempotency key would pay out twice."

  - id: refund_requires_verified_customer
    description: Refunds go only to customers whose identity has been verified.
    when: {tool: issue_refund}
    check: "crm.customer_verified(crm.order_customer(order_id))"
    on_fail: BLOCK
    risk: HIGH
    message: "The customer who owns this order is not verified, so it cannot be refunded."

  - id: grant_only_active_users
    description: Access is granted only to current employees.
    when: {tool: grant_access}
    check: "iam.user_active(user_id)"
    on_fail: BLOCK
    risk: HIGH
    message: "The employee is not active, so no access can be granted."

  - id: grant_matches_request
    description: A grant must match its access request exactly (user, system and role).
    when: {tool: grant_access}
    check: "iam.request_field(request_id, 'user_id') == user_id and iam.request_field(request_id, 'system_id') == system_id and iam.request_field(request_id, 'role') == role"
    on_fail: BLOCK
    risk: CRITICAL
    message: "The grant does not match what was requested; agents may not widen access."

  - id: segregation_of_duties
    description: Nobody may both write payments and write the payments audit log.
    when: {tool: grant_access}
    check: "not ((system_id == 'SYS-AUDIT' and role != 'read' and iam.has_grant(user_id, 'SYS-PAY', 'write')) or (system_id == 'SYS-PAY' and role != 'read' and iam.has_grant(user_id, 'SYS-AUDIT', 'write')))"
    on_fail: BLOCK
    risk: CRITICAL
    message: "Segregation of duties: the employee would be able to both move payments and edit the audit log."

  - id: privileged_access_approval
    description: Admin access to high or critical systems needs a person to approve it.
    when: {tool: grant_access}
    check: "not (role == 'admin' and iam.system_sensitivity(system_id) in ['high', 'critical'])"
    on_fail: REQUIRE_APPROVAL
    risk: HIGH
    message: "Admin access to a high or critical system needs human approval."

  - id: grant_duration
    description: Grants expire; critical systems within 30 days, everything else within 90.
    when: {tool: grant_access}
    check: "days <= 90 and (days <= 30 or iam.system_sensitivity(system_id) != 'critical')"
    on_fail: BLOCK
    risk: MEDIUM
    message: "Access must expire within 90 days (30 for critical systems)."

sequences:
  - id: secret_exfiltration
    description: Secrets must never leave through an external tool, even encoded.
    sources: [SECRET]
    sinks: [send_email, notify, http_post]
    through_transforms: [encode]
    on_match: BLOCK
    risk: CRITICAL

  - id: bulk_pii_exfiltration
    description: Bulk customer data must not leave through an external tool without a human approving it.
    sources: [PII_BULK]
    sinks: [send_email, notify, http_post]
    through_transforms: [encode]
    on_match: REQUIRE_APPROVAL
    risk: HIGH

# Ordered action-sequence rules over the calls executed so far in the session.
patterns:
  - id: refund_without_verification
    description: Refunds must follow a successful lookup of the customer and of the same order.
    when: {tool: issue_refund}
    requires_prior:
      - {tool: get_customer, ok: true}
      - {tool: get_order, ok: true, args: {order_id: "$order_id"}}
    on_match: REQUIRE_APPROVAL
    risk: HIGH

  - id: act_after_untrusted
    description: A write or external action right after untrusted (possibly injected) content needs a human.
    when: {side_effect: [write, external]}
    after_label: {label: UNTRUSTED, within_calls: 3}
    on_match: REQUIRE_APPROVAL
    risk: HIGH

  - id: irreversible_burst
    description: More than two refunds in a short span is never part of a normal support task.
    when: {tool: issue_refund}
    rate: {max: 2, within_calls: 10}
    on_match: BLOCK
    risk: CRITICAL

# Post-action verification: confirm effects in the system of record before the agent sees "success".
verify:
  - id: refund_landed
    description: A refund the payments API reports as successful must exist in the ledger.
    tool: issue_refund
    check: "ledger.refund_key_exists(idempotency_key)"
    on_fail: fail
    risk: HIGH
    message: "The refund is not in the ledger."

  - id: grant_landed
    description: An access grant reported as done must exist in the directory.
    tool: grant_access
    check: "iam.has_grant(user_id, system_id, role)"
    on_fail: fail
    risk: HIGH
    message: "The grant is not in the directory."
